package pe.metago;import android.app.*;import android.content.*;import java.util.*;public class Reminder extends BroadcastReceiver{public static void schedule(Context c){android.content.SharedPreferences p=c.getSharedPreferences("meta",0);if(!p.contains("hour"))return;Calendar t=Calendar.getInstance();t.set(Calendar.HOUR_OF_DAY,p.getInt("hour",20));t.set(Calendar.MINUTE,p.getInt("minute",0));t.set(Calendar.SECOND,0);t.set(Calendar.MILLISECOND,0);if(t.getTimeInMillis()<=System.currentTimeMillis())t.add(Calendar.DAY_OF_YEAR,1);PendingIntent pi=PendingIntent.getBroadcast(c,1,new Intent(c,Reminder.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);c.getSystemService(AlarmManager.class).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);}public void onReceive(Context c,Intent i){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("save","Ahorro diario",NotificationManager.IMPORTANCE_DEFAULT));long a=c.getSharedPreferences("meta",0).getLong("daily",1500);PendingIntent pi=PendingIntent.getActivity(c,2,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(1,new Notification.Builder(c,"save").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("MetaGO · Tu futuro te espera").setContentText(String.format(Locale.US,"Hoy puedes ahorrar S/ %.2f",a/100.0)).setContentIntent(pi).setAutoCancel(true).build());schedule(c);}}